import{_ as a,o as e,c as d,a2 as s}from"./chunks/framework.Cd7uensT.js";const b=JSON.parse('{"title":"端口自动采集","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features/port-collection.md","filePath":"guide/features/port-collection.md","lastUpdated":1794561975000}'),n={name:"guide/features/port-collection.md"};function r(o,t,i,l,p,c){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="端口自动采集" tabindex="-1">端口自动采集 <a class="header-anchor" href="#端口自动采集" aria-label="Permalink to &quot;端口自动采集&quot;">​</a></h1><p>端口自动采集通过登录交换机或服务器 BMC，读取设备真实的端口与硬件配置，与系统台账比对后按差异落库，避免逐条手工录入。</p><blockquote><p><strong>版本要求</strong>：需 <strong>v2.8.0 及以上</strong>。v2.8.2 补齐了批量落库的四向冲突检查。</p></blockquote><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐方式</th><th>说明</th></tr></thead><tbody><tr><td>新交换机上架</td><td>SSH / SNMP 采集</td><td>一次性同步全部端口与状态</td></tr><tr><td>服务器上架</td><td>Redfish 带外采集</td><td>同时获得硬件清单（CPU/内存/硬盘/网卡）</td></tr><tr><td>定期核对</td><td>重新采集比对差异</td><td>发现现场改配后未同步的端口</td></tr><tr><td>板卡扩容</td><td>重新采集</td><td><code>added</code> 分区即为新增端口</td></tr><tr><td>拆板卡 / 换设备</td><td>重新采集</td><td><code>removed</code> 分区即为已消失端口</td></tr></tbody></table><h2 id="采集前准备" tabindex="-1">采集前准备 <a class="header-anchor" href="#采集前准备" aria-label="Permalink to &quot;采集前准备&quot;">​</a></h2><h3 id="_1-网络可达性" tabindex="-1">1. 网络可达性 <a class="header-anchor" href="#_1-网络可达性" aria-label="Permalink to &quot;1. 网络可达性&quot;">​</a></h3><p>采集主机（后端服务所在服务器）必须能访问目标设备：</p><table tabindex="0"><thead><tr><th>协议</th><th>默认端口</th><th>目标类型</th></tr></thead><tbody><tr><td>SSH</td><td>22</td><td>交换机、路由器、防火墙</td></tr><tr><td>Telnet</td><td>23</td><td>老旧网络设备</td></tr><tr><td>SNMP</td><td>161 (UDP)</td><td>任意支持 SNMP 的网络设备</td></tr><tr><td>Redfish</td><td>443 / 80</td><td>服务器 BMC（iDRAC / iLO / iBMC）</td></tr></tbody></table><p>验证方式（在采集主机上执行）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SSH</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">telnet</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.10.1.11</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SNMP（需安装 snmpwalk）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">snmpwalk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v2c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.10.1.11</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysDescr</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Redfish</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://10.10.1.20/redfish/v1</span></span></code></pre></div><h3 id="_2-采集账号" tabindex="-1">2. 采集账号 <a class="header-anchor" href="#_2-采集账号" aria-label="Permalink to &quot;2. 采集账号&quot;">​</a></h3><p>建议<strong>为采集单独创建只读账号</strong>，不要使用管理员账号：</p><table tabindex="0"><thead><tr><th>设备类型</th><th>所需权限</th><th>举例（华为）</th></tr></thead><tbody><tr><td>华为交换机</td><td>网络只读 + <code>display</code> 命令</td><td><code>local-user netadmin password irreversible-cipher ...</code> / <code>local-user netadmin privilege level 1</code></td></tr><tr><td>H3C 交换机</td><td><code>network-operator</code> 角色</td><td><code>local-user netadmin</code> / <code>authorization-attribute user-role network-operator</code></td></tr><tr><td>Cisco 交换机</td><td>privilege 15 或自定义只读视图</td><td><code>username netadmin privilege 15 secret ...</code></td></tr><tr><td>锐捷交换机</td><td>只读权限</td><td><code>username netadmin privilege 1</code></td></tr><tr><td>服务器 BMC</td><td>只读 / Operator</td><td>iDRAC：Setup → User Accounts → 角色设为 <code>Operator</code></td></tr></tbody></table><h3 id="_3-ssrf-防护检查" tabindex="-1">3. SSRF 防护检查 <a class="header-anchor" href="#_3-ssrf-防护检查" aria-label="Permalink to &quot;3. SSRF 防护检查&quot;">​</a></h3><p>采集目标受系统级安全策略约束：</p><table tabindex="0"><thead><tr><th>系统设置项</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>allow_intranet_collection</code></td><td><code>true</code></td><td>是否允许访问私网目标。<strong>关闭后拒绝所有私网地址，会中断核心采集业务</strong></td></tr><tr><td><code>target_whitelist</code></td><td>空数组</td><td>非空时，私网目标必须落在白名单 CIDR 内</td></tr></tbody></table><blockquote><p>若采集报「目标地址不被允许」，请先检查这两项设置，而非账号问题。</p></blockquote><h2 id="操作流程" tabindex="-1">操作流程 <a class="header-anchor" href="#操作流程" aria-label="Permalink to &quot;操作流程&quot;">​</a></h2><h3 id="交换机端口采集" tabindex="-1">交换机端口采集 <a class="header-anchor" href="#交换机端口采集" aria-label="Permalink to &quot;交换机端口采集&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 设备管理 → 选择目标交换机 → 打开详情</span></span>
<span class="line"><span>2. 切换到「采集凭据」区块 → 新增凭据</span></span>
<span class="line"><span>   - 协议：SSH（推荐）或 SNMP</span></span>
<span class="line"><span>   - 地址、端口、用户名、口令</span></span>
<span class="line"><span>   - 厂商：可留空，系统会连接后自动识别</span></span>
<span class="line"><span>   - 勾选「设为默认凭据」</span></span>
<span class="line"><span>3. 点击「连接测试」验证凭据可用</span></span>
<span class="line"><span>4. 进入端口管理 → 选择该设备 → 点击「端口采集」</span></span>
<span class="line"><span>5. 系统返回差异预览：</span></span>
<span class="line"><span>   - 新增端口（设备有、系统无）</span></span>
<span class="line"><span>   - 变更端口（属性不一致，逐字段列出）</span></span>
<span class="line"><span>   - 多余端口（系统有、设备无）</span></span>
<span class="line"><span>6. 勾选需要落库的分区 → 执行应用</span></span></code></pre></div><h3 id="凭据连接测试结果解读" tabindex="-1">凭据连接测试结果解读 <a class="header-anchor" href="#凭据连接测试结果解读" aria-label="Permalink to &quot;凭据连接测试结果解读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>结果</th><th>含义</th><th>下一步</th></tr></thead><tbody><tr><td>连接成功</td><td>协议、账号、网络均正常</td><td>继续采集</td></tr><tr><td>认证失败</td><td>账号或口令错误</td><td>核对凭据；必要时用 <code>/raw</code> 端点读取明文比对</td></tr><tr><td>连接超时</td><td>网络不通或端口被拦</td><td>检查防火墙与路由</td></tr><tr><td>协议不匹配</td><td>设备不支持所选协议</td><td>更换协议（如从 SSH 改为 SNMP）</td></tr><tr><td>厂商不支持</td><td>驱动未适配</td><td>手工填写厂商，或按通用模板采集</td></tr></tbody></table><h3 id="支持的厂商" tabindex="-1">支持的厂商 <a class="header-anchor" href="#支持的厂商" aria-label="Permalink to &quot;支持的厂商&quot;">​</a></h3><table tabindex="0"><thead><tr><th>厂商标识</th><th>设备类型</th><th>采集方式</th></tr></thead><tbody><tr><td><code>huawei</code></td><td>华为</td><td>SSH / Telnet</td></tr><tr><td><code>h3c</code></td><td>H3C 华三</td><td>SSH / Telnet</td></tr><tr><td><code>cisco</code></td><td>思科</td><td>SSH / Telnet</td></tr><tr><td><code>ruijie</code></td><td>锐捷</td><td>SSH / Telnet</td></tr><tr><td><code>generic</code></td><td>通用</td><td>SNMP（IF-MIB，厂商无关）</td></tr></tbody></table><blockquote><p><strong>厂商识别策略</strong>：优先使用凭据中已配置的 <code>vendor</code>；未配置时，系统连接后执行 <code>display version</code> / <code>show version</code> 自动识别。SNMP 方式从 <code>sysDescr</code> 识别，识别失败退回 <code>generic</code> 且<strong>不阻断采集</strong>（IF-MIB 本身厂商无关）。</p></blockquote><h3 id="服务器带外采集" tabindex="-1">服务器带外采集 <a class="header-anchor" href="#服务器带外采集" aria-label="Permalink to &quot;服务器带外采集&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 设备管理 → 选择服务器 → 详情 → 采集凭据</span></span>
<span class="line"><span>   - 协议：redfish</span></span>
<span class="line"><span>   - 地址：BMC 管理地址（不是操作系统地址）</span></span>
<span class="line"><span>   - 用户名 / 口令：BMC 账号</span></span>
<span class="line"><span>2. 连接测试</span></span>
<span class="line"><span>3. 端口管理 → 该设备 → 「服务器采集」</span></span>
<span class="line"><span>4. 差异预览同时包含：</span></span>
<span class="line"><span>   - 硬件清单（CPU、内存、硬盘、电源、风扇、网络适配器）</span></span>
<span class="line"><span>   - 端口差异</span></span>
<span class="line"><span>5. 执行应用</span></span></code></pre></div><p><strong>服务器采集的额外效果</strong>：</p><table tabindex="0"><thead><tr><th>结果</th><th>落库位置</th></tr></thead><tbody><tr><td>硬件清单</td><td><code>Device.customFields.hardware</code>（JSON）</td></tr><tr><td>网络适配器</td><td>自动创建/更新 <code>NetworkCard</code> 记录，命名为 <code>网卡1</code>、<code>网卡2</code>…</td></tr><tr><td>端口</td><td><code>device_ports</code> 表，按差异落库</td></tr></tbody></table><blockquote><p>已存在的同名网卡执行更新（型号/厂商/端口数/描述），<strong>不会删除手工创建的其他网卡</strong>，因此人工补充的网卡信息不会被采集覆盖。</p></blockquote><h2 id="差异分区处理建议" tabindex="-1">差异分区处理建议 <a class="header-anchor" href="#差异分区处理建议" aria-label="Permalink to &quot;差异分区处理建议&quot;">​</a></h2><h3 id="新增端口-added" tabindex="-1">新增端口（added） <a class="header-anchor" href="#新增端口-added" aria-label="Permalink to &quot;新增端口（added）&quot;">​</a></h3><p><strong>默认落库</strong>。建议全选，这是采集的主要价值。</p><h3 id="变更端口-changed" tabindex="-1">变更端口（changed） <a class="header-anchor" href="#变更端口-changed" aria-label="Permalink to &quot;变更端口（changed）&quot;">​</a></h3><p><strong>默认落库</strong>。常见变更：</p><table tabindex="0"><thead><tr><th>变更字段</th><th>可能原因</th></tr></thead><tbody><tr><td><code>portSpeed</code></td><td>更换光模块或协商降速</td></tr><tr><td><code>status</code></td><td>端口从 down 变为 up</td></tr><tr><td><code>description</code></td><td>现场改了端口描述</td></tr></tbody></table><blockquote><p>若变更内容与你的台账语义冲突（例如 OFFICE 环境手工维护了业务描述，不希望被设备上的默认描述覆盖），可取消勾选 <code>changed</code>，仅落库新增端口。</p></blockquote><h3 id="多余端口-removed" tabindex="-1">多余端口（removed） <a class="header-anchor" href="#多余端口-removed" aria-label="Permalink to &quot;多余端口（removed）&quot;">​</a></h3><p><strong>默认不落库</strong>。这是刻意的保守设计：</p><ul><li>采集失败的部分结果可能造成「所有端口都消失」的误判</li><li>删端口会连带影响接线记录</li><li>建议在确认板卡确实拆除后，手工在端口管理页面删除</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：采集结果显示端口数为 0 或只有管理口？</strong></p><p>可能原因：</p><ol><li>使用了 SNMP 但设备的 IF-MIB 未开放（部分设备需显式启用）</li><li>SSH 账号权限不足，无法执行 <code>display interface brief</code></li><li>设备处于堆叠/集群模式，主设备只能看到自身端口</li></ol><p>处理：先用 <code>discover</code> 预览查看原始返回，确认是驱动解析问题还是设备侧限制。</p><p><strong>Q：应用差异时提示「非法的端口字段变更」？</strong></p><p>差异对象由前端回传，服务端会校验 <code>fieldChanges</code> 的字段名是否在允许清单内。该提示说明前端提交了非端口字段（如 <code>portId</code>、<code>deviceId</code>）。通常由旧版本前端缓存导致，刷新页面后重新采集即可。</p><p><strong>Q：采集会不会覆盖我手工录入的端口描述？</strong></p><p><code>changed</code> 分区默认勾选时，设备侧的描述会覆盖系统内记录。若你依赖手工维护的业务描述，建议在应用时<strong>取消勾选 <code>changed</code></strong>，或采集前先备份端口数据。</p><p><strong>Q：同一台设备可以配置多个凭据吗？</strong></p><p>可以。同一设备可对每种协议各有一条「默认凭据」，采集时未指定 <code>credentialId</code> 则自动使用对应协议的默认凭据。更换账号时新建凭据并设为默认即可，旧凭据可保留备用。</p><p><strong>Q：采集需要多长时间？</strong></p><p>取决于设备规模与协议：SSH 通常 5~30 秒（与端口数量正相关）；SNMP 约 3~10 秒；Redfish 服务器因需逐项查询硬件，通常 10~60 秒。</p><p><strong>Q：采集失败会留下脏数据吗？</strong></p><p>不会。<code>discover</code> 阶段完全不写库；<code>apply</code> 阶段在单个数据库事务中执行，任一步失败整体回滚。</p><h2 id="安全注意事项" tabindex="-1">安全注意事项 <a class="header-anchor" href="#安全注意事项" aria-label="Permalink to &quot;安全注意事项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>建议</th></tr></thead><tbody><tr><td>凭据存储</td><td>口令与 SNMP 团体名 AES-256-GCM 加密落库，接口返回掩码</td></tr><tr><td>明文读取</td><td>仅超级管理员可使用 <code>/raw</code> 端点，且会记入操作日志</td></tr><tr><td>账号权限</td><td>采集账号应为只读，避免误操作设备</td></tr><tr><td>网络隔离</td><td>采集主机与设备建议处于同一管理网段，通过防火墙限定来源</td></tr><tr><td>密钥轮换</td><td>若使用 <code>REMOTE_BACKUP_KEY</code> 独立密钥，轮换前须先执行 <code>scripts/migrate-remote-backup-cipher.js</code> 重加密存量凭据</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/idc_assest-docs/api/port-collection.html">端口采集与设备凭据接口</a></li><li><a href="/idc_assest-docs/api/ports.html">设备端口接口</a></li><li><a href="./device-management.html">设备管理</a></li></ul>`,60)])])}const u=a(n,[["render",r]]);export{b as __pageData,u as default};
